import { Table, StringColumn, DecimalColumn, ChoiceColumn } from '@servicenow/sdk/core'

export const sn_appstore_pending_user_onboard_log = Table({
    label: 'SN App Store Pending User Onboard Log',
    name: 'sn_appstore_pending_user_onboard_log',
    schema: {
        user: StringColumn({}),
        try_count: DecimalColumn({
            default: '0',
        }),
        status: ChoiceColumn({
            default: 'logged',
            choices: {
                logged: {
                    label: 'Logged',
                },
                resolved: {
                    label: 'Resolved',
                },
                unable_to_resolve: {
                    label: 'Unable to Resolve',
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Status',
        }),
    },
})
